"""Generate the reviewed Brotato section using the site's shared layout."""
from pathlib import Path
from html import escape
import json
from site_analytics import write_html
from brotato_content import PAGES,STORE,BASE,NEWS,PRESS,link,p,table
ROOT=Path(__file__).resolve().parents[1]
PREFIX='/brotato/'
AD='<script async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-8830315294299920" crossorigin="anonymous"></script>'
MEDIA=json.loads((ROOT/'data/brotato-media.json').read_text(encoding='utf8'))
NAV=[('Start here',PREFIX),('Evolution',PREFIX+'evolution/'),('Co-op',PREFIX+'co-op/'),('Guides',PREFIX+'#guides'),('More games','/#more-games')]

def figure(key, loading='lazy'):
 m=MEDIA[key]
 return f'<figure class="game-image"><a href="{m["path"]}"><img src="{m["path"]}" width="{m["width"]}" height="{m["height"]}" alt="{escape(m["alt"],quote=True)}" loading="{loading}"></a><figcaption>{m["caption"]} {link(m["source"],"Image source")}</figcaption></figure>'

def shell(route,title,desc,body,image='steam-0',error=False):
 nav=''.join(f'<a href="{u}">{t}</a>'for t,u in NAV)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)}</title><meta name="description" content="{escape(desc,quote=True)}"><link rel="canonical" href="https://megabonk.org{route}"><meta property="og:type" content="article"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:url" content="https://megabonk.org{route}"><meta property="og:image" content="https://megabonk.org{MEDIA[image]['path']}">{'<meta name="robots" content="noindex,follow">'if error else AD}<link rel="icon" href="/assets/brotato/favicon.ico"><link rel="apple-touch-icon" href="/assets/brotato/icon-180.png"><link rel="stylesheet" href="/assets/pokebonk/site.css"><link rel="stylesheet" href="/assets/guide-article-layout.css"><link rel="stylesheet" href="/assets/vampire-survivors/site.css"><link rel="stylesheet" href="/assets/brotato/site.css"></head><body class="guide-layout vs-guide brotato"><a class="skip" href="#main">Skip to content</a><header class="top"><div class="wrap"><a class="brand" href="/brotato/"><img src="/assets/brotato/logo.svg" width="44" height="44" alt=""><span>Brotato<small>Megabonk.org · Independent guides</small></span></a><nav class="desktop-nav" aria-label="Brotato navigation">{nav}</nav><details class="mobile-nav"><summary>Menu</summary><nav class="mobile-links" aria-label="Brotato mobile navigation">{nav}</nav></details></div></header><main class="wrap" id="main">{body}</main><footer class="footer"><div class="wrap footer-grid"><div><strong>Megabonk.org editors</strong><p>Independent guides. Not affiliated with Blobfish Games or Evil Empire. Game artwork belongs to its owners.</p><a href="/#more-games">More games →</a></div><nav aria-label="Site information"><a href="/about/">About</a><a href="/contact/">Contact</a><a href="/privacy-policy">Privacy</a></nav></div></footer></body></html>'''

def article(slug,title,desc,answer,image,sections):
 toc='<nav class="toc" aria-label="On this page">'+''.join(f'<a href="#{i}">{h}</a>'for i,h,_ in sections)+'</nav>'
 review_date='14 November 2026' if slug in {'evolution','caveman','co-op','updates','mods'} else ('9 November 2026' if slug=='vs-vampire-survivors' else '13 November 2026')
 body=f'<header class="article-head" id="guide"><p class="tag">BROTATO · FIELD GUIDE</p><h1>{title}</h1><div class="answer"><p>{answer}</p></div><p class="byline">Megabonk.org editors · Checked {review_date} · Source-based guidance, no gameplay test</p></header><div class="article-layout">'+toc+'<article class="prose">'
 for n,(i,h,t) in enumerate(sections):
  body+=f'<section id="{i}"><h2>{h}</h2>{t}</section>'
  if n==0:body+=figure(image)
 body+='<section class="related"><h2>Choose your next task</h2>'+''.join(f'<a href="{PREFIX+s}/">{t}</a>'for s,t in [('evolution','Evolution choices'),('updates','Branch and Item Sets'),('co-op','Co-op setup')]if s!=slug)+'</section><p><a href="#guide">Back to top ↑</a></p></article></div>'
 return shell(PREFIX+slug+'/',title,desc,body,image)

def home():
 cards=''.join(f'<a class="task-card" href="{PREFIX+s}/"><h3>{t}</h3><p>{a}</p><span>Read guide →</span></a>'for s,t,d,a,im,se in PAGES)
 body=f'<section class="bt-hero" id="guide"><div><p class="tag">BROTATO · PRIMAL DREAD FIELD NOTES</p><h1>Make the next shop count.</h1><p class="lead">Choose an Evolution path, plan a character and get your co-op session ready.</p><p>Primal Dread is available on PC. Console and mobile versions are announced for early 2027, with no exact day confirmed in the checked publisher briefing.</p><a class="button" href="#setup">Check your DLC setup →</a><p>Checked 13 November 2026 · Independent, source-based guides</p></div><div>{figure("steam-0", "eager")}</div></section><section class="section" id="guides"><h2>Choose the task in front of you</h2><div class="bt-grid">{cards}</div></section>'
 body+='<div class="article-layout"><article class="prose"><section id="setup"><h2>Primal Dread installation and platform check</h2>'+table(['Your copy','Action','Why'],[['Steam PC, base game owned','Install the DLC in the same Steam account, then inspect Item Sets.','Steam says the base game is required.'],['No base game','Compare the base game plus DLC bundle against separate purchases.','Primal Dread is expansion content.'],['PS5, PS4, Xbox, Switch or Switch 2','Wait for a platform-specific Primal Dread listing and confirmed launch.','Publisher briefing gives early 2027, not an exact day.'],['iOS or Android','Check the mobile publisher’s own listing when available.','The PC DLC purchase does not establish mobile ownership.'],['Steam Deck','Use the Steam PC entitlement path.','A console release window is a separate question.']])+p(link(STORE,'Steam DLC listing')+' confirms the base-game requirement. '+link(PRESS,'Publisher press briefing')+' gives the console and mobile window. Check your region’s storefront before purchasing.')+'</section>'+figure('item-set')+'<section id="missing"><h2>If installed content is missing</h2><ol><li>Confirm the DLC is owned by the account running the base game.</li><li>In Steam Library → Brotato → Properties → DLC, check installation.</li><li>Update and restart the game.</li><li>Open Item Sets from Character Selection and inspect Primal Dread.</li><li>If the issue persists, record the game version, branch and active mods before asking support.</li></ol>'+p('The developer’s '+link(NEWS,'1.2 announcement')+' explains that Item Sets can disable expansions and free updates. A missing shop item can be an enabled-content issue. Use the <a href="/brotato/mods/">mod checklist</a> if the updated game crashes.')+'</section><section id="buy"><h2>Choose expansion content by the run you want</h2>'+p('Primal Dread adds the Jungle, Evolution and new characters, weapons and items. Abyssal Terrors is a separate expansion. If your goal is learning the base loop, begin with a simpler enabled-content set. Choose Primal Dread when you want to manage the trade-off between stronger weapon or item scaling and changed enemy hazards. Use our <a href="/brotato/evolution/">Evolution guide</a> to understand that decision.')+p('The 12 November Steam Balancing Patch brings the tested Evolution and shop changes to the default branch. Check the <a href="/brotato/updates/">branch guide</a> and <a href="/brotato/evolution/">Evolution choices</a> before copying a launch build.')+p('New Dawn appears separately in Item Sets. It is not another name for Primal Dread. See <a href="/brotato/updates/">the update and branch guide</a> when a video appears to show different rules.')+'</section><section id="references"><h2>Reference and community routes</h2>'+p('Use '+link(BASE,'Steam’s base-game page')+' for the official product, '+link(NEWS,'developer announcements')+' for patches, and '+link('https://www.reddit.com/r/brotato/','r/brotato')+' for player discussion. Include map, branch, difficulty and Item Sets when asking for build help. '+link('https://steamdb.info/app/1942280/','SteamDB')+' is a third-party history and statistics service. Its player figures are not search volume.')+p('These pages synthesize public sources. Character reports retain their own source limitations. We have not completed game runs, tested multiplayer hardware or verified mod packages.')+'</section></article></div>'
 return shell(PREFIX,'Brotato Guides — Primal Dread Setup, Evolution and Co-op','Set up Brotato Primal Dread, check console timing, choose Evolution and find source-based Caveman, Veteran, co-op and update guides.',body)

def build():
 for page in PAGES:
  f=ROOT/'brotato'/page[0]/'index.html';f.parent.mkdir(parents=True,exist_ok=True);write_html(f,article(*page),encoding='utf8')
 write_html(ROOT/'brotato/index.html',home(),encoding='utf8')
 write_html(ROOT/'brotato/404.html',shell('/brotato/404','Page not found | Brotato Guides','Find a Brotato task guide.','<article class="legal"><h1>Page not found</h1><p><a href="/brotato/">Return to Brotato guides</a></p></article>',error=True),encoding='utf8')
 f=ROOT/'index.html';write_html(f,f.read_text(encoding='utf8'),encoding='utf8')
 print('Built Brotato hub, seven task pages and scoped 404')
if __name__=='__main__':build()
